/// <summary>
/// finds NDXUtilitasDataETIM record
/// </summary>
/// <param name = "_refRecId">RecId of NDXUtilitasData record</param>
/// <param name = "_schemaName">schema name</param>
/// <param name = "_aidName">AID name</param>
/// <param name = "_update">for update</param>
/// <returns>NDXUtilitasDataETIM record</returns>
static NDXUtilitasDataETIM find(RefRecId _refRecId, str 20 _schemaName, NDXAIDName _aidName, boolean _update = false)
{
    NDXUtilitasDataETIM lNDXUtilitasDataETIM;

    lNDXUtilitasDataETIM.selectForUpdate(_update);

    if(_refRecId > 0 && _schemaName && _aidName)
    {
        select firstOnly lNDXUtilitasDataETIM
            where lNDXUtilitasDataETIM.NDXUtilitasDataRefRecId == _refRecId
                && lNDXUtilitasDataETIM.SchemaName == _schemaName
                && lNDXUtilitasDataETIM.AIDName == _aidName;

    }

    return lNDXUtilitasDataETIM;
}

/// <summary>
/// finds or creates NDXUtilitasDataETIM record
/// </summary>
/// <param name = "_refRecId">RecId of NDXUtilitasData record</param>
/// <param name = "_etim">Etim object</param>
/// <returns>NDXUtilitasDataETIM record</returns>
static NDXUtilitasDataETIM findOrCreateByObject(RefRecId _refRecId, Niedax.Utilitas.UtilitasDataContractETIM _etim)
{
    NDXUtilitasDataETIM lNDXUtilitasDataETIM;
    NDXSchemaName schemaName = _etim.get_SchemaName();
    NDXAIDName aidName = _etim.get_AIdName();
    str 255 value = _etim.get_Value();
    UnitIdBase unitId =  _etim.get_UnitId();


    if(_refRecId && schemaNAme && AIDName)
    {
        lNDXUtilitasDataETIM = NDXUtilitasDataETIM::find(_refRecId, schemaNAme, aidName, true);

        if(!lNDXUtilitasDataETIM)
        {
            lNDXUtilitasDataETIM.NDXUtilitasDataRefRecId = _refRecId;
            lNDXUtilitasDataETIM.SchemaName = schemaNAme;
            lNDXUtilitasDataETIM.AIDName = aidName;
            lNDXUtilitasDataETIM.insert();
        }

        lNDXUtilitasDataETIM.Value = StrLRTrim(value);
        lNDXUtilitasDataETIM.UnitId = StrLRTrim(unitId);

        ttsbegin;
        lNDXUtilitasDataETIM.doUpdate();
        ttscommit;

    }

    return lNDXUtilitasDataETIM;
}
